package com.classapp.data
import androidx.room.*
import com.classapp.model.*

@Dao interface StudentDao { @Query("SELECT * FROM students ORDER BY firstName,lastName") suspend fun all():List<Student>; @Query("SELECT * FROM students WHERE code LIKE :q OR firstName LIKE :q OR lastName LIKE :q OR mobile LIKE :q OR nationalId LIKE :q ORDER BY firstName") suspend fun search(q:String):List<Student>; @Insert(onConflict=OnConflictStrategy.REPLACE) suspend fun upsert(x:Student); @Insert(onConflict=OnConflictStrategy.REPLACE) suspend fun upsertAll(x:List<Student>); @Delete suspend fun delete(x:Student); @Query("DELETE FROM students") suspend fun clear() }
@Dao interface TeacherDao { @Query("SELECT * FROM teachers ORDER BY name") suspend fun all():List<Teacher>; @Insert(onConflict=OnConflictStrategy.REPLACE) suspend fun upsert(x:Teacher); @Insert(onConflict=OnConflictStrategy.REPLACE) suspend fun upsertAll(x:List<Teacher>); @Query("DELETE FROM teachers") suspend fun clear() }
@Dao interface CourseDao { @Query("SELECT * FROM courses ORDER BY name") suspend fun all():List<Course>; @Insert(onConflict=OnConflictStrategy.REPLACE) suspend fun upsert(x:Course); @Insert(onConflict=OnConflictStrategy.REPLACE) suspend fun upsertAll(x:List<Course>); @Query("DELETE FROM courses") suspend fun clear() }
@Dao interface ClassDao { @Query("SELECT * FROM school_classes ORDER BY startDate,name") suspend fun all():List<SchoolClass>; @Insert(onConflict=OnConflictStrategy.REPLACE) suspend fun upsert(x:SchoolClass); @Insert(onConflict=OnConflictStrategy.REPLACE) suspend fun upsertAll(x:List<SchoolClass>); @Query("DELETE FROM school_classes") suspend fun clear() }
@Dao interface EnrollmentDao { @Query("SELECT * FROM enrollments") suspend fun all():List<Enrollment>; @Insert(onConflict=OnConflictStrategy.REPLACE) suspend fun upsert(x:Enrollment); @Insert(onConflict=OnConflictStrategy.REPLACE) suspend fun upsertAll(x:List<Enrollment>); @Query("DELETE FROM enrollments") suspend fun clear() }
@Dao interface AttendanceDao { @Query("SELECT * FROM attendance ORDER BY date DESC") suspend fun all():List<Attendance>; @Insert(onConflict=OnConflictStrategy.REPLACE) suspend fun upsert(x:Attendance); @Insert(onConflict=OnConflictStrategy.REPLACE) suspend fun upsertAll(x:List<Attendance>); @Query("DELETE FROM attendance") suspend fun clear() }
@Dao interface PaymentDao { @Query("SELECT * FROM payments ORDER BY date DESC") suspend fun all():List<Payment>; @Insert(onConflict=OnConflictStrategy.REPLACE) suspend fun upsert(x:Payment); @Insert(onConflict=OnConflictStrategy.REPLACE) suspend fun upsertAll(x:List<Payment>); @Query("DELETE FROM payments") suspend fun clear() }
@Dao interface GradeDao { @Query("SELECT * FROM grades ORDER BY date DESC") suspend fun all():List<Grade>; @Insert(onConflict=OnConflictStrategy.REPLACE) suspend fun upsert(x:Grade); @Insert(onConflict=OnConflictStrategy.REPLACE) suspend fun upsertAll(x:List<Grade>); @Query("DELETE FROM grades") suspend fun clear() }
@Dao interface DailyReportDao { @Query("SELECT * FROM daily_reports ORDER BY date DESC,createdAt DESC") suspend fun all():List<DailyReport>; @Query("SELECT * FROM daily_reports WHERE date BETWEEN :from AND :to ORDER BY date DESC") suspend fun between(from:String,to:String):List<DailyReport>; @Insert(onConflict=OnConflictStrategy.REPLACE) suspend fun upsert(x:DailyReport); @Insert(onConflict=OnConflictStrategy.REPLACE) suspend fun upsertAll(x:List<DailyReport>); @Query("DELETE FROM daily_reports") suspend fun clear() }
